7	//   <script id="__NEXT_DATA__" type="application/json">
8	//     { "props": { "pageProps": { "data": { "event": {
9	//       "title": "Sophie Duker: Hot Beef Injection",
10	//       "description": "...",
11	//       "duration": 60,
12	//       "venues": [ { "title": "Pleasance Courtyard",
13	//                      "address1": "60 Pleasance", "postCode": "EH8 9TJ" } ],
14	//       "spaces": [ { "venueName": "Forth at Pleasance Courtyard" } ],
