464	  L.push("");
465	  L.push("| Host | Cases | Events found (fb/custom) | Critical % | All % |");
466	  L.push("| --- | --: | --: | --: | --: |");
467	  for (const h of Object.values(cov.hosts).sort((a, b) => a.host.localeCompare(b.host))) {
468	    L.push(
469	      `| \`${h.host}\` | ${h.caseCount} | ${h.eventsCovered}/${h.customEvents} | ` +
470	        `${pct(h.criticalHits, h.criticalGradeable)}% | ${pct(h.allHits, h.allGradeable)}% |`
471	    );
