476	  // fails, this shows which case/field regressed without re-running the old
477	  // version to find it.
478	  L.push("## By exemplar");
479	  L.push("");
480	  L.push("Legend: ✓ match · ~ different value · ✗ missing (source had it, the bare run didn't) · — source left it empty");
481	  L.push("");
