493	}
494	
495	// The notable value differences — fields where the bare run produced a wrong or
496	// weaker value rather than just missing one. Emitted as TEST OUTPUT (not written
497	// to the committed report) so the actual mismatched values are there to guide
498	// future generic-extractor work without bloating the artifact. Returns "" when there are
499	// none.
500	function renderNotableDifferences(cov) {
501	  const L = ["Bare generic values that DIFFER from the dedicated source (wrong/weaker, not merely missing):"];
502	  let any = false;
503	  for (const c of cov.cases) {
504	    const diffs = ALL_FIELDS.filter((f) => c.cells[f].state === "diff");
505	    if (!diffs.length) continue;
506	    any = true;
507	    L.push(`  ${c.name}`);
508	    for (const f of diffs) {
509	      L.push(`    ${f}: custom [${cell(c.cells[f].custom)}]  vs  bare [${cell(c.cells[f].bare)}]`);
510	    }
511	  }
512	  if (!any) L.push("  (none)");
513	  return L.join("\n");
514	}
515	
516	function fmtWm(watermark, key) {
517	  return watermark && typeof watermark[key] === "number" ? `${watermark[key]}%` : "—";
518	}
519	
520	module.exports = {
521	  computeCoverage,
522	  renderMarkdown,
523	  renderNotableDifferences,
524	  gateStatus,
525	  nextBaseline,
526	  subsetScore,
527	  ALL_FIELDS,
528	  CRITICAL_FIELDS,
529	  pct,
530	};
