import { readFileSync } from "node:fs";
import path from "node:path";
import { JSDOM } from "jsdom";

const ROOT = process.cwd();
const EXT = path.join(ROOT, "extension");
const name = process.argv[2];
const { dataFile } = await import(path.join(ROOT, "dev/requirements/extractor/data-files.js"));

const url = readFileSync(dataFile(`${name}.url`), "utf8").trim();
const html = readFileSync(dataFile(`${name}.html`), "utf8");

const files = JSON.parse(readFileSync(path.join(EXT, "event-extractors/load-order.generated.json"), "utf8"));
const sources = files.map((f) => readFileSync(path.join(EXT, f), "utf8"));

const dom = new JSDOM(html, { url, runScripts: "outside-only" });
for (const src of sources) dom.window.eval(src);
dom.window.eval("GCal.sources = [];");
const bare = dom.window.eval("JSON.stringify(GCal.extract(), null, 2)");
console.log("URL:", url);
console.log("BARE:", bare);
console.log("---");
console.log("og:site_name:", dom.window.eval('GCal.meta("og:site_name")'));
console.log("og:title:", dom.window.eval('GCal.meta("og:title")'));
console.log("og:description:", dom.window.eval('GCal.meta("og:description")'));
console.log("description meta:", dom.window.eval('GCal.meta("description")'));
dom.window.close();

